"use strict";

/**
 * LP2 original p40-p53 delta-channel degree-eight GF(29) recurrence gate.
 *
 * Source cues: the red eight-rune p40 heading, eight printed columns in the
 * pp49-51 numeral table, and the original highly suppressed adjacent-equal
 * ciphertext steps. Hypothesis: after the red heading, the 3,000 body rune
 * deltas are generated by one eight-register linear recurrence over GF(29).
 * Repeated ciphertext runes are exceptional zero steps that do not advance
 * this recurrence's register clock. The first body step is measured against
 * the last heading rune. No key, phase, direction, field, or coefficient is
 * fitted to the withheld half.
 *
 * An impossible first 17 nonzero steps exclude every such stationary
 * degree-eight recurrence, regardless of the eight hidden coefficients.
 *
 * Windows 11 / Node.js 22: node sims/lp2_p40_delta8_nonzero_lfsr_sft.cjs
 * Standalone SFT. Only canonical repository data is read; no files written.
 */
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.resolve(__dirname, "..");
const corpus = JSON.parse(fs.readFileSync(
  path.join(ROOT, "resources/liber-primus/lp2-corpus.json"), "utf8"
));
const MOD = 29;
const ORDER = 8;
const mod = value => ((value % MOD) + MOD) % MOD;

/** @param {number} value @returns {number} */
function inverse(value) {
  for (let i = 1; i < MOD; i++) {
    if (mod(value * i) === 1) return i;
  }
  throw new Error("Non-invertible GF29 coefficient");
}

/**
 * Fit exactly eight coefficients from the first sixteen nonzero source steps.
 * Equations are step[t+8] = sum(coeff[j] * step[t+j]) mod 29.
 *
 * @param {number[]} stream
 * @returns {number[]}
 */
function fitEight(stream) {
  assert.ok(stream.length >= 2 * ORDER);
  const matrix = Array.from({length: ORDER}, (_, t) =>
    stream.slice(t, t + ORDER).concat(stream[t + ORDER]));
  for (let col = 0; col < ORDER; col++) {
    let pivot = col;
    while (pivot < ORDER && matrix[pivot][col] === 0) pivot++;
    assert.ok(pivot < ORDER, "Training matrix has no unique order-eight fit");
    [matrix[col], matrix[pivot]] = [matrix[pivot], matrix[col]];
    const factor = inverse(matrix[col][col]);
    for (let j = col; j <= ORDER; j++) {
      matrix[col][j] = mod(matrix[col][j] * factor);
    }
    for (let row = 0; row < ORDER; row++) {
      if (row === col) continue;
      const weight = matrix[row][col];
      for (let j = col; j <= ORDER; j++) {
        matrix[row][j] = mod(matrix[row][j] - weight * matrix[col][j]);
      }
    }
  }
  return matrix.map(row => row[ORDER]);
}

/** @param {number[]} steps @param {number} initial */
function integrate(steps, initial) {
  let value = initial;
  return steps.map(step => {
    value = mod(value + step);
    return value;
  });
}

/** @param {number[]} cipher @param {number} initial */
function differences(cipher, initial) {
  let prev = initial;
  return cipher.map(value => {
    const step = mod(value - prev);
    prev = value;
    return step;
  });
}

/** @param {number[]} stream @param {number[]} coefficients @param {number} t */
function predict(stream, coefficients, t) {
  let result = 0;
  for (let j = 0; j < ORDER; j++) {
    result += coefficients[j] * stream[t - ORDER + j];
  }
  return mod(result);
}

/** @param {number[]} stream @param {number[]} coefficients @param {number} start */
function matches(stream, coefficients, start) {
  let passed = 0;
  for (let t = start; t < stream.length; t++) {
    if (predict(stream, coefficients, t) === stream[t]) passed++;
  }
  return passed;
}

const chapter = corpus.pages.filter(page =>
  page.page >= 40 && page.page <= 53).flatMap(page => page.indices);
assert.equal(chapter.length, 3008);
const redHeading = chapter.slice(0, 8);
assert.equal(redHeading.length, 8);
const body = chapter.slice(8);
assert.equal(body.length, 3000);
const steps = differences(body, redHeading[7]);
assert.deepEqual(integrate(steps, redHeading[7]), body,
  "Complete original 3,000-rune forward round trip failed");
const zeroPositions = steps.flatMap((v, i) => v === 0 ? [i] : []);
assert.equal(zeroPositions.length, 18);
const nonzero = steps.filter(value => value !== 0);
assert.equal(nonzero.length, 2982);
const trainCount = nonzero.length / 2;
assert.equal(trainCount, 1491);
const coefficients = fitEight(nonzero.slice(0, trainCount));
assert.deepEqual(coefficients, [0, 19, 17, 25, 16, 20, 13, 13]);

let firstFailure = ORDER;
while (firstFailure < nonzero.length &&
       predict(nonzero, coefficients, firstFailure) === nonzero[firstFailure]) {
  firstFailure++;
}
assert.equal(firstFailure, 16);
const firstPrediction = predict(nonzero, coefficients, firstFailure);
assert.equal(firstPrediction, 22);
assert.equal(nonzero[firstFailure], 27);

const trainingMatches = matches(nonzero.slice(0, trainCount),
  coefficients, ORDER);
let withheldMatches = 0;
for (let t = trainCount; t < nonzero.length; t++) {
  if (predict(nonzero, coefficients, t) === nonzero[t]) withheldMatches++;
}
assert.equal(trainingMatches, 68);
assert.equal(withheldMatches, 61);
assert.equal(trainCount - ORDER, 1483);
assert.equal(nonzero.length - trainCount, 1491);

/*
 * Native GP29 positive control: construct an eight-register recurrence of
 * exact period eight using eight prime-derived nonzero GP steps. Insert
 * the same 18 original zero-marker locations without clock advance.
 * Recover its unrestricted eight secret coefficients, all 2,982 predictions,
 * and every reconstructed 3,000-rune cipher symbol. The control exercises
 * the complete original data geometry, including exceptional zero steps.
 */
const plantedSeed = [3, 5, 7, 11, 13, 17, 19, 23];
const plantedNonzero = Array.from({length: nonzero.length},
  (_, i) => plantedSeed[i % ORDER]);
const plantedSteps = steps.map((value, i) => value === 0 ? 0 : undefined);
let at = 0;
for (let i = 0; i < plantedSteps.length; i++) {
  if (plantedSteps[i] === undefined) plantedSteps[i] = plantedNonzero[at++];
}
assert.equal(at, nonzero.length);
const plantedCipher = integrate(plantedSteps, redHeading[7]);
assert.deepEqual(differences(plantedCipher, redHeading[7]), plantedSteps);
const recovered = fitEight(plantedSteps.filter(value => value !== 0));
assert.deepEqual(recovered, [1, 0, 0, 0, 0, 0, 0, 0]);
assert.equal(matches(plantedNonzero, recovered, ORDER),
  nonzero.length - ORDER, "Native 8-register plant must fully recover");

const corruptedPlant = plantedNonzero.slice();
corruptedPlant[100] = mod(corruptedPlant[100] + 1);
assert.ok(corruptedPlant[100] !== 0);
assert.equal(matches(corruptedPlant, recovered, ORDER),
  nonzero.length - ORDER - 2,
  "One changed input must break current and next period-eight prediction");

console.log(JSON.stringify({
  original: {
    pages: "p40-p53",
    headingRunes: redHeading.length,
    bodyRunes: body.length,
    originalRoundTrip: true,
    observedZeroSteps: zeroPositions.length,
    nonzeroSteps: nonzero.length,
    trainedOnFirst: trainCount,
    frozenOrder: ORDER,
    field: "GF(29)",
    coefficients,
    earliestOriginalContradiction: {
      nonzeroStepIndex: firstFailure,
      observed: nonzero[firstFailure],
      predicted: firstPrediction
    },
    trainOneStepMatches: trainingMatches,
    trainOneStepTotal: trainCount - ORDER,
    withheldOneStepMatches: withheldMatches,
    withheldOneStepTotal: nonzero.length - trainCount
  },
  planted: {
    exactCipherRoundTrip: true,
    trueCoefficientsRecovered: recovered,
    heldoutPredictions: nonzero.length - ORDER,
    wrongSampleRejected: true
  },
  verdict: "This fixed original GF29 degree-eight difference recurrence is impossible."
}, null, 2));
